INSERT INTO versiones_firmware (id,version,chip,tipo_dispositivo,descripcion,manifiesto,directorio,ubicacion_archivo,publicado,descontinuado,creado_por)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM versiones_firmware),'1.0.4','ESP32-S3','sensores',
'Diagnostico en campo sin monitor serie: al conectar informa al backend el motivo del ultimo reinicio (BROWNOUT = caida de tension de la fuente, PANIC, WDT), que queda en los logs del sistema. Potencia WiFi a 15 dBm para bajar los picos de corriente con fuentes DC; watchdog de 5 min y reinicio si pasa 5 min sin MQTT, en vez de quedar mudo. Conserva la verificacion NVS de 1.0.3.',
'{"schema_version": 1, "version": "1.0.4", "chip": "ESP32-S3", "tipo_dispositivo": "sensores", "source_sha256": "340eeb0e97234b9163c073a8a6ff8c5ed51c6391e5041ae7a4acb228663e1d33", "segmentos": [{"nombre": "esp32_s3.ino.bootloader.bin", "direccion": 0, "tamano": 19968, "sha256": "5f95cbc8b40b7a373f9cb85b534cb7a570cdad30ca27c7021775d830ca03276b"}, {"nombre": "esp32_s3.ino.partitions.bin", "direccion": 32768, "tamano": 3072, "sha256": "148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1"}, {"nombre": "boot_app0.bin", "direccion": 57344, "tamano": 8192, "sha256": "f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0"}, {"nombre": "esp32_s3.ino.bin", "direccion": 65536, "tamano": 1023376, "sha256": "5b3bc46782fdabb1185362fccadded074105453c37fa37ad70764a92f1fa582c"}]}'::jsonb,'esp32-s3-1.0.4','firmware_store/esp32-s3-1.0.4',true,false,
(SELECT MIN(id) FROM usuarios WHERE id_rol=1)
WHERE EXISTS (SELECT 1 FROM usuarios WHERE id_rol=1) AND NOT EXISTS
(SELECT 1 FROM versiones_firmware WHERE version='1.0.4' AND chip='ESP32-S3' AND tipo_dispositivo='sensores');
UPDATE versiones_firmware SET
descripcion='Diagnostico en campo sin monitor serie: al conectar informa al backend el motivo del ultimo reinicio (BROWNOUT = caida de tension de la fuente, PANIC, WDT), que queda en los logs del sistema. Potencia WiFi a 15 dBm para bajar los picos de corriente con fuentes DC; watchdog de 5 min y reinicio si pasa 5 min sin MQTT, en vez de quedar mudo. Conserva la verificacion NVS de 1.0.3.',
